import React, { useState } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { ShoppingCart, Menu, X, Coffee, LogOut, User } from 'lucide-react';
import { useAuth } from '../context/AuthContext';
import { useCart } from '../context/CartContext';

export default function Navbar() {
  const { user, logout, isAuth } = useAuth();
  const { count } = useCart();
  const navigate = useNavigate();
  const location = useLocation();
  const [mobileOpen, setMobileOpen] = useState(false);
  const [userMenu, setUserMenu] = useState(false);

  const handleLogout = () => { logout(); navigate('/login'); setUserMenu(false); setMobileOpen(false); };
  const isActive = path => location.pathname === path ? 'active' : '';

  const links = [
    { to: '/', label: 'Home' },
    { to: '/menu', label: 'Menu' },
    { to: '/booking', label: 'Book a Table' },
    { to: '/offers', label: 'Offers' },
    { to: '/contact', label: 'Contact' },
  ];

  return (
    <nav className="navbar">
      <div className="navbar-inner">
        <Link to="/" className="navbar-logo">
          <Coffee size={26} color="#d4762a" />
          <span className="navbar-logo-text">BrewHaven</span>
        </Link>

        <div className="navbar-links">
          {links.map(l => (
            <Link key={l.to} to={l.to} className={`navbar-link ${isActive(l.to)}`} onClick={() => setMobileOpen(false)}>
              {l.label}
            </Link>
          ))}
        </div>

        <div className="navbar-actions">
          <Link to="/cart" className="cart-btn">
            <ShoppingCart size={20} />
            {count > 0 && <span className="cart-badge">{count}</span>}
          </Link>

          {isAuth ? (
            <div style={{ position: 'relative' }}>
              <button className="user-btn" onClick={() => setUserMenu(!userMenu)}>
                <div className="user-avatar">{user?.username?.[0]?.toUpperCase()}</div>
                <span className="user-name">{user?.first_name || user?.username}</span>
              </button>
              {userMenu && (
                <div className="dropdown">
                  <Link to="/profile" className="drop-item" onClick={() => setUserMenu(false)}>
                    <User size={15} /> My Profile
                  </Link>
                  <Link to="/orders" className="drop-item" onClick={() => setUserMenu(false)}>
                    📦 My Orders
                  </Link>
                  <Link to="/bookings" className="drop-item" onClick={() => setUserMenu(false)}>
                    📅 My Bookings
                  </Link>
                  <hr style={{ border: 'none', borderTop: '1px solid #e8ddd4', margin: '4px 0' }} />
                  <button className="drop-item" style={{ color: '#e53935' }} onClick={handleLogout}>
                    <LogOut size={15} /> Logout
                  </button>
                </div>
              )}
            </div>
          ) : (
            <Link to="/login" className="login-btn">Sign In</Link>
          )}

          <button className="hamburger" onClick={() => setMobileOpen(!mobileOpen)}>
            {mobileOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
        </div>
      </div>

      <div className={`mobile-menu ${mobileOpen ? 'open' : ''}`}>
        {links.map(l => (
          <Link key={l.to} to={l.to} className="mobile-link" onClick={() => setMobileOpen(false)}>{l.label}</Link>
        ))}
        <hr style={{ border: 'none', borderTop: '1px solid #e8ddd4', margin: '6px 0' }} />
        {isAuth ? (
          <>
            <Link to="/profile" className="mobile-link" onClick={() => setMobileOpen(false)}>👤 My Profile</Link>
            <Link to="/orders" className="mobile-link" onClick={() => setMobileOpen(false)}>📦 My Orders</Link>
            <Link to="/bookings" className="mobile-link" onClick={() => setMobileOpen(false)}>📅 My Bookings</Link>
            <button className="mobile-link" style={{ border: 'none', background: 'none', color: '#e53935', cursor: 'pointer', textAlign: 'left', width: '100%', fontFamily: 'DM Sans, sans-serif', fontSize: 15 }} onClick={handleLogout}>🚪 Logout</button>
          </>
        ) : (
          <Link to="/login" className="mobile-link" onClick={() => setMobileOpen(false)}>🔑 Sign In</Link>
        )}
      </div>
    </nav>
  );
}
